#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

// Quantos votos cada jogo recebeu.
map<string, int> contarVotos(const vector<string>& votos) {
    map<string, int> contagem;
    for (const string& voto : votos) {
        contagem[voto]++;
    }
    return contagem;
}

// O jogo com mais votos (empate: o primeiro em ordem alfabética); "" se não houver votos.
string vencedor(const map<string, int>& contagem) {
    string melhor = "";
    int maisVotos = 0;
    for (const auto& par : contagem) {
        if (par.second > maisVotos) {
            melhor = par.first;
            maisVotos = par.second;
        }
    }
    return melhor;
}

int main() {
    vector<string> votos;
    string voto;
    cout << "Voto: ";
    cin >> voto;
    while (voto != "fim") {
        votos.push_back(voto);
        cout << "Voto: ";
        cin >> voto;
    }
    map<string, int> contagem = contarVotos(votos);
    for (const auto& par : contagem) {
        cout << par.first << ": " << par.second << endl;
    }
    cout << "Vencedor: " << vencedor(contagem) << endl;
    return 0;
}

