#include <iostream>
#include <set>
#include <string>
#include <utility>
using namespace std;

// Muda x e y de acordo com a direção: N, S, L ou O. (Já está pronta.)
void andar(char direcao, int& x, int& y) {
    if (direcao == 'N') {
        y++;
    } else if (direcao == 'S') {
        y--;
    } else if (direcao == 'L') {
        x++;
    } else if (direcao == 'O') {
        x--;
    }
}

// Posição (x, y) no fim do caminho, começando em (0, 0).
pair<int, int> posicaoFinal(const string& caminho) {
    int x = 0, y = 0;
    for (char c : caminho) {
        andar(c, x, y);
    }
    return {x, y};
}

// Quantas casas diferentes foram pisadas, contando a inicial.
int casasVisitadas(const string& caminho) {
    int x = 0, y = 0;
    set<pair<int, int>> visitadas = {{0, 0}};
    for (char c : caminho) {
        andar(c, x, y);
        visitadas.insert({x, y});
    }
    return static_cast<int>(visitadas.size());
}

int main() {
    string caminho;
    cout << "Caminho: ";
    cin >> caminho;
    pair<int, int> fim = posicaoFinal(caminho);
    cout << "Posição final: (" << fim.first << ", " << fim.second << ")" << endl;
    cout << "Casas visitadas: " << casasVisitadas(caminho) << endl;
    return 0;
}

