#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

struct Monstro {
    string nome;
    int vida;
};

// Apaga os monstros com vida <= 0 (mantendo a ordem) e devolve quantos apagou.
int removerDerrotados(vector<Monstro>& monstros) {
    int removidos = 0;
    for (auto it = monstros.begin(); it != monstros.end(); ) {
        if (it->vida <= 0) {
            it = monstros.erase(it);
            removidos++;
        } else {
            ++it;
        }
    }
    return removidos;
}

// Apaga os itens com quantidade 0 e devolve quantos apagou.
int removerEsgotados(map<string, int>& estoque) {
    int removidos = 0;
    for (auto it = estoque.begin(); it != estoque.end(); ) {
        if (it->second == 0) {
            it = estoque.erase(it);
            removidos++;
        } else {
            ++it;
        }
    }
    return removidos;
}

int main() {
    vector<Monstro> arena = {{"Slime", 5}, {"Goblin", 0}, {"Rato", -2}, {"Orc", 12}};
    cout << "Derrotados removidos: " << removerDerrotados(arena) << endl;
    cout << "Na arena:";
    for (const Monstro& m : arena) {
        cout << " " << m.nome;
    }
    cout << endl;

    map<string, int> estoque = {{"arco", 2}, {"elmo", 0}, {"gema", 5}};
    cout << "Itens esgotados: " << removerEsgotados(estoque) << endl;
    cout << "No estoque:";
    for (const auto& par : estoque) {
        cout << " " << par.first;
    }
    cout << endl;
    return 0;
}

