#include <iostream>
#include <functional>
#include <vector>
using namespace std;

// Devolve uma lambda que multiplica o dano por fator.
function<int(int)> multiplicar(int fator) {
    return [fator](int dano) { return dano * fator; };
}

// Devolve uma lambda que tira reducao do dano (nunca abaixo de 0).
function<int(int)> escudo(int reducao) {
    return [reducao](int dano) {
        int resto = dano - reducao;
        return resto > 0 ? resto : 0;
    };
}

// Passa o dano por cada efeito, em ordem, e devolve o resultado.
int aplicar(int dano, const vector<function<int(int)>>& efeitos) {
    int resultado = dano;
    for (const auto& efeito : efeitos) {
        resultado = efeito(resultado);
    }
    return resultado;
}

int main() {
    int golpe = 12;
    cout << "Golpe normal: " << aplicar(golpe, {}) << endl;
    cout << "Com poção de força: " << aplicar(golpe, {multiplicar(3)}) << endl;
    cout << "Com poção e escudo: " << aplicar(golpe, {multiplicar(3), escudo(5)}) << endl;
    cout << "Ordem trocada: " << aplicar(golpe, {escudo(5), multiplicar(3)}) << endl;
    return 0;
}

