#include <iostream>
#include <algorithm>
#include <optional>
#include <string>
#include <vector>
using namespace std;

struct Heroi {
    string nome;
    string classe;
    int nivel;
};

// Classe em ordem alfabética; na mesma classe, nível maior primeiro.
void ordenarGuilda(vector<Heroi>& guilda) {
    sort(guilda.begin(), guilda.end(), [](const Heroi& a, const Heroi& b) {
        if (a.classe != b.classe) {
            return a.classe < b.classe;
        }
        return a.nivel > b.nivel;
    });
}

// Quantos heróis têm nível >= nivelMinimo.
int contarDoNivel(const vector<Heroi>& guilda, int nivelMinimo) {
    return count_if(guilda.begin(), guilda.end(),
                    [nivelMinimo](const Heroi& h) { return h.nivel >= nivelMinimo; });
}

