#include <iostream>
#include <algorithm>
#include <map>
#include <optional>
#include <string>
#include <utility>
#include <vector>
using namespace std;

struct Partida {
    string jogador;
    int pontos;
};

// Total de pontos de cada jogador.
map<string, int> somarPontos(const vector<Partida>& partidas) {
    map<string, int> totais;
    for (const Partida& p : partidas) {
        totais[p.jogador] += p.pontos;
    }
    return totais;
}

// Pares (nome, total): total maior primeiro; empate pelo nome.
vector<pair<string, int>> montarRanking(const map<string, int>& totais) {
    vector<pair<string, int>> ranking(totais.begin(), totais.end());
    sort(ranking.begin(), ranking.end(), [](const pair<string, int>& a, const pair<string, int>& b) {
        if (a.second != b.second) {
            return a.second > b.second;
        }
        return a.first < b.first;
    });
    return ranking;
}

// Colocação (1, 2, 3...) do jogador no ranking, ou nullopt.
optional<int> posicao(const vector<pair<string, int>>& ranking, const string& nome) {
    auto it = find_if(ranking.begin(), ranking.end(),
                      [&nome](const pair<string, int>& p) { return p.first == nome; });
    if (it == ranking.end()) {
        return nullopt;
    }
    return static_cast<int>(it - ranking.begin()) + 1;
}

int main() {
    vector<Partida> partidas;
    string nome;
    int pontos = 0;
    cout << "Jogador (ou fim): ";
    cin >> nome;
    while (nome != "fim") {
        cout << "Pontos: ";
        cin >> pontos;
        partidas.push_back({nome, pontos});
        cout << "Jogador (ou fim): ";
        cin >> nome;
    }

    vector<pair<string, int>> ranking = montarRanking(somarPontos(partidas));
    cout << "=== RANKING ===" << endl;
    for (size_t i = 0; i < ranking.size(); i++) {
        cout << i + 1 << ". " << ranking[i].first << " - " << ranking[i].second << endl;
    }

    string buscado;
    cout << "Buscar: ";
    cin >> buscado;
    optional<int> pos = posicao(ranking, buscado);
    if (pos) {
        cout << buscado << " está na posição " << *pos << "." << endl;
    } else {
        cout << buscado << " não está no ranking." << endl;
    }
    return 0;
}
